package migratex

import (
	"context"
	"database/sql"
	"fmt"
	"path/filepath"
	"strings"
	"time"

	_ "modernc.org/sqlite" // pure-Go SQLite driver: no cgo, no shell dependency
)

// sqliteSource reads from a SQLite database file.
//
// The file is opened read-only through the DSN's mode parameter, so no statement
// can modify the customer's database even if one were generated by mistake.
type sqliteSource struct {
	db *sql.DB
}

// NewSQLiteSource opens a SQLite database read-only.
func NewSQLiteSource(ctx context.Context, cfg ConnectionConfig) (Source, error) {
	if cfg.Path == "" {
		return nil, fmt.Errorf("path is required for a SQLite source")
	}
	abs, err := filepath.Abs(cfg.Path)
	if err != nil {
		return nil, fmt.Errorf("resolve sqlite path: %w", err)
	}
	dsn := "file:" + abs + "?mode=ro&_pragma=query_only(1)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite database: %w", err)
	}
	db.SetMaxOpenConns(2)
	db.SetConnMaxLifetime(time.Minute)
	if err := db.PingContext(ctx); err != nil {
		db.Close()
		return nil, fmt.Errorf("open sqlite database: %w", err)
	}
	return &sqliteSource{db: db}, nil
}

func (s *sqliteSource) Kind() SourceKind { return SourceSQLite }

func (s *sqliteSource) TestConnection(ctx context.Context) error {
	var one int
	if err := s.db.QueryRowContext(ctx, "SELECT 1").Scan(&one); err != nil {
		return fmt.Errorf("sqlite connection test failed: %w", err)
	}
	// Confirm the query_only pragma took effect.
	var queryOnly int
	if err := s.db.QueryRowContext(ctx, "PRAGMA query_only").Scan(&queryOnly); err != nil {
		return fmt.Errorf("could not read the query_only pragma: %w", err)
	}
	if queryOnly != 1 {
		return fmt.Errorf("the SQLite session is not read-only; refusing to continue")
	}
	return nil
}

func (s *sqliteSource) DiscoverSchema(ctx context.Context) ([]TableSchema, error) {
	const q = `
		SELECT name FROM sqlite_master
		WHERE type = 'table' AND name NOT LIKE 'sqlite_%'
		ORDER BY name`
	rows, err := s.db.QueryContext(ctx, q)
	if err != nil {
		return nil, fmt.Errorf("list sqlite tables: %w", err)
	}
	defer rows.Close()

	var names []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		names = append(names, name)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	out := make([]TableSchema, 0, len(names))
	for _, name := range names {
		quoted, err := quoteIdentifier(name)
		if err != nil {
			continue
		}
		infoRows, err := s.db.QueryContext(ctx, "PRAGMA table_info("+quoted+")")
		if err != nil {
			continue
		}
		table := TableSchema{Name: name}
		for infoRows.Next() {
			var (
				cid        int
				colName    string
				colType    string
				notNull    int
				defaultV   any
				primaryKey int
			)
			if err := infoRows.Scan(&cid, &colName, &colType, &notNull, &defaultV, &primaryKey); err != nil {
				infoRows.Close()
				break
			}
			table.Columns = append(table.Columns, ColumnInfo{
				Name: colName, Type: colType, Nullable: notNull == 0, PrimaryKey: primaryKey > 0,
			})
		}
		infoRows.Close()
		out = append(out, table)
	}
	return out, nil
}

func (s *sqliteSource) CountRows(ctx context.Context, table string) (int64, error) {
	quoted, err := quoteIdentifier(table)
	if err != nil {
		return 0, err
	}
	var n int64
	if err := s.db.QueryRowContext(ctx, "SELECT count(*) FROM "+quoted).Scan(&n); err != nil {
		return 0, fmt.Errorf("count rows in %s: %w", table, err)
	}
	return n, nil
}

func (s *sqliteSource) ReadBatch(ctx context.Context, table string, columns []string,
	watermark map[string]any, limit int) ([]map[string]any, error) {

	quotedTable, err := quoteIdentifier(table)
	if err != nil {
		return nil, err
	}
	if len(columns) == 0 {
		return nil, fmt.Errorf("at least one column is required")
	}
	quotedCols := make([]string, 0, len(columns))
	for _, c := range columns {
		q, err := quoteIdentifier(c)
		if err != nil {
			return nil, err
		}
		quotedCols = append(quotedCols, q)
	}
	if limit <= 0 || limit > 100000 {
		limit = 1000
	}
	orderBy := ""
	if col, ok := watermark["column"].(string); ok && col != "" {
		q, err := quoteIdentifier(col)
		if err != nil {
			return nil, err
		}
		orderBy = " ORDER BY " + q + " ASC"
	}

	q := fmt.Sprintf("SELECT %s FROM %s%s LIMIT ?", strings.Join(quotedCols, ", "), quotedTable, orderBy)
	rows, err := s.db.QueryContext(ctx, q, limit)
	if err != nil {
		return nil, fmt.Errorf("read from %s: %w", table, err)
	}
	defer rows.Close()

	colNames, err := rows.Columns()
	if err != nil {
		return nil, err
	}
	var out []map[string]any
	for rows.Next() {
		values := make([]any, len(colNames))
		ptrs := make([]any, len(colNames))
		for i := range values {
			ptrs[i] = &values[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			return nil, err
		}
		rec := make(map[string]any, len(colNames))
		for i, name := range colNames {
			rec[name] = normaliseValue(values[i])
		}
		out = append(out, rec)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if since, ok := watermark["value"]; ok && since != nil && len(out) > 0 {
		col, _ := watermark["column"].(string)
		out = filterAfter(out, col, since)
	}
	return out, nil
}

func (s *sqliteSource) Close() error { return s.db.Close() }
